"""Small, curated answers for common ocean-science questions."""
from __future__ import annotations

import re


ANSWERS = (
    (r"\b(tide|tides)\b", "Tides are the regular rise and fall of sea level, caused mainly by the Moon's gravity and also by the Sun. Coastline shape and water depth affect local tide times and heights."),
    (r"\b(current|currents)\b", "Ocean currents are large-scale flows of seawater. They are driven by wind, differences in temperature and salinity, Earth's rotation, and the shape of coastlines and the seafloor."),
    (r"\b(wave|waves|swell)\b", "Most ocean surface waves are generated by wind transferring energy to the water. Swell is wave energy that has travelled away from the weather that created it."),
    (r"\b(marine life|marine ecosystem|food web|biodiversity)\b", "Marine life ranges from microscopic plankton to large whales. These organisms interact in food webs, recycle nutrients, and depend on habitats such as open water, seagrass beds, mangroves, and reefs."),
    (r"\b(coral|reef|reefs|bleach|bleaching)\b", "Coral reefs are diverse marine habitats built by coral animals. Heat stress can cause corals to lose the algae they depend on, leading to bleaching; prolonged stress can kill them."),
    (r"\b(salinity|salty|salt)\b", "Seawater is salty because weathering releases dissolved minerals from rocks and rivers carry them to the ocean. Water evaporates but most dissolved salts remain, so they accumulate over time."),
    (r"\b(tsunami|tsunamis)\b", "A tsunami is a series of long waves usually caused by sudden displacement of the seafloor, often during an underwater earthquake. It is different from an ordinary wind-generated wave."),
    (r"\b(acidification|acidic|ocean acid)\b", "Ocean acidification happens as seawater absorbs carbon dioxide from the air. The added carbon dioxide changes seawater chemistry and makes it harder for some organisms to build shells and skeletons."),
    (r"\b(plastic|pollution|pollutants|marine debris)\b", "Ocean pollution includes plastics, chemicals, sewage, oil, and excess nutrients entering marine environments. It can injure wildlife, damage habitats, and move through food webs."),
    (r"\b(phytoplankton|chlorophyll)\b", "Phytoplankton are tiny drifting organisms that use sunlight for photosynthesis. They form the base of many marine food webs and produce a substantial share of Earth's oxygen."),
    (r"\b(sea level|sea-level)\b", "Global sea level rises mainly because warming seawater expands and melting land ice adds water to the ocean. Local sea-level change also depends on land movement, currents, and regional ocean conditions."),
    (r"\b(ocean|oceans|sea|seas)\b", "Oceans are connected bodies of salt water that regulate climate, store heat and carbon, support marine life, and shape weather. I can explain topics such as currents, tides, waves, reefs, pollution, or ocean climate."),
)

_EXPLANATION_CUES = re.compile(r"\b(what|why|how|explain|define|meaning|tell me about|describe)\b", re.IGNORECASE)
_LOCAL_CUES = re.compile(r"\b(weather|forecast|safe|safety|conditions|fishing|fish|near|around|tomorrow|today|tonight|alert|warning)\b", re.IGNORECASE)


def answer_ocean_question(query: str) -> str | None:
    """Answer a supported general ocean question without requiring a location."""
    if not _EXPLANATION_CUES.search(query) or _LOCAL_CUES.search(query):
        return None

    for pattern, answer in ANSWERS:
        if re.search(pattern, query, re.IGNORECASE):
            return answer
    return None
